import{_ as l,b as a,c as t,g as e}from"./chunks/framework.86O3EbG5.js";const h=JSON.parse('{"title":"自动规划","description":"","frontmatter":{"title":"自动规划","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/11.md","filePath":"articles/ai/books/ai-modern-approach/11.md"}'),o={name:"articles/ai/books/ai-modern-approach/11.md"};function r(d,i,n,s,_,c){return a(),t("div",null,[...i[0]||(i[0]=[e('<p>第 11 章在第 10 章经典规划的基础上，进一步放松「完全可观测」「确定性」「静态」等假设，关注真实世界中的规划与执行。核心主题是：当规划执行过程中可能出现意外（动作失败、感知与预期不符）时，智能体应如何行动。重点包括：</p><h2 id="非确定性环境中的规划" tabindex="-1">非确定性环境中的规划</h2><ul><li>动作结果可能有多重可能（如移动机器人可能打滑）</li><li>解的形式不再是动作序列，而是条件规划（分支计划）或循环规划</li><li>使用与或图表示：或节点（智能体选择动作）、与节点（环境产生分支）</li></ul><h2 id="条件规划" tabindex="-1">条件规划</h2><ul><li>包含感知动作（如 Check(条件)），根据感知结果选择不同后续动作</li><li>通过搜索与或图生成，保证无论环境如何，智能体都能达到目标</li></ul><h2 id="循环规划" tabindex="-1">循环规划</h2><ul><li>当环境可无限持续（如保持房间清洁），规划可能包含循环</li><li>需证明循环终将终止（通常借助势函数）</li></ul><h2 id="执行监控与重新规划" tabindex="-1">执行监控与重新规划</h2><ul><li>在执行过程中，若实际感知与预期不符，则触发重新规划</li><li>规划监视器（plan monitor）检测偏差，决定是继续、修整计划还是完全重新规划</li></ul><h2 id="连续规划" tabindex="-1">连续规划</h2><ul><li>时间、资源约束的规划问题</li><li>使用调度与资源分配方法（如关键路径法、资源约束调度）</li></ul><h2 id="分层规划" tabindex="-1">分层规划</h2><ul><li>高层动作（HLA）的分解方法（如 HTN 规划）</li><li>天使语义、REACH*、逐步细化</li></ul>',13)])])}const u=l(o,[["render",r]]);export{h as __pageData,u as default};
